param([switch]$RenderOnly)
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
Add-Type -AssemblyName System.Drawing
$root=Split-Path $PSScriptRoot -Parent
$diagrams=Join-Path $root 'Chapter 3 Diagrams'
$model=Get-Content -Raw -Encoding UTF8 (Join-Path $diagrams '_Sources/security-paper-model.json')|ConvertFrom-Json
# Render exactly the same primitives as the editable SVG/draw.io figures.
foreach($stem in @('03a-login-security-stores','05a-administrator-security-schema')){
 $drawing=Get-Content -Raw -Encoding UTF8 (Join-Path $diagrams "_Sources/$stem.json")|ConvertFrom-Json
 $bmp=[Drawing.Bitmap]::new([int]$drawing.W,[int]$drawing.H);$g=[Drawing.Graphics]::FromImage($bmp)
 $pen=[Drawing.Pen]::new([Drawing.Color]::Black,2);$font=[Drawing.Font]::new('Arial',22,[Drawing.FontStyle]::Regular,[Drawing.GraphicsUnit]::Pixel)
 try{$g.Clear([Drawing.Color]::White);$g.SmoothingMode='AntiAlias';$g.TextRenderingHint='AntiAliasGridFit'
  foreach($p in $drawing.items){
   if($p.kind -eq 'store'){$g.DrawLine($pen,[single]$p.x,[single]$p.y,[single]($p.x+$p.w),[single]$p.y);$g.DrawLine($pen,[single]$p.x,[single]$p.y,[single]$p.x,[single]($p.y+$p.h));$g.DrawLine($pen,[single]$p.x,[single]($p.y+$p.h),[single]($p.x+$p.w),[single]($p.y+$p.h));$g.DrawLine($pen,[single]($p.x+64),[single]$p.y,[single]($p.x+64),[single]($p.y+$p.h))}
   if($p.kind -eq 'box'){$color=if($p.fill){[Drawing.ColorTranslator]::FromHtml($p.fill)}else{[Drawing.Color]::White};$brush=[Drawing.SolidBrush]::new($color);try{$g.FillRectangle($brush,[single]$p.x,[single]$p.y,[single]$p.w,[single]$p.h);$g.DrawRectangle($pen,[single]$p.x,[single]$p.y,[single]$p.w,[single]$p.h)}finally{$brush.Dispose()}}
   elseif($p.kind -eq 'text'){$g.DrawString($p.text,$font,[Drawing.Brushes]::Black,[single]$p.x,[single]$p.y)}
   elseif($p.kind -eq 'line'){$points=[Drawing.PointF[]]@($p.points|ForEach-Object {[Drawing.PointF]::new([single]$_[0],[single]$_[1])});$g.DrawLines($pen,$points)
    foreach($end in @(0,1)){if(($end -eq 0 -and -not $p.both) -or ($end -eq 1 -and -not $p.arrow)){continue};$a=if($end -eq 0){$points[0]}else{$points[-1]};$b=if($end -eq 0){$points[1]}else{$points[-2]};$angle=[Math]::Atan2($a.Y-$b.Y,$a.X-$b.X);$tri=[Drawing.PointF[]]@($a,[Drawing.PointF]::new($a.X-13*[Math]::Cos($angle-.45),$a.Y-13*[Math]::Sin($angle-.45)),[Drawing.PointF]::new($a.X-13*[Math]::Cos($angle+.45),$a.Y-13*[Math]::Sin($angle+.45)));$g.FillPolygon([Drawing.Brushes]::Black,$tri)}
   }
  };$bmp.Save((Join-Path $diagrams "_Sources/$stem.png"),[Drawing.Imaging.ImageFormat]::Png)
 }finally{$g.Dispose();$bmp.Dispose();$pen.Dispose();$font.Dispose()}
}
if($RenderOnly){return}
$backup=Join-Path $root ('Review Backups/security-paper-'+(Get-Date -Format yyyyMMdd-HHmmss));New-Item -ItemType Directory -Path $backup -Force|Out-Null
$w='http://schemas.openxmlformats.org/wordprocessingml/2006/main';$a='http://schemas.openxmlformats.org/drawingml/2006/main';$relNs='http://schemas.openxmlformats.org/officeDocument/2006/relationships'
$flow=@(
'Administrator device authorization is part of User Login rather than an additional main function. Password authentication establishes an Auth session but does not by itself authorize an administrator dashboard or scanner session. The server checks the active role, application scope, current trusted public key and authorized session mapping. A session may access protected operations only after the applicable device-verification workflow completes. Staff and member login retain their role-specific checks.',
'First registration and return visits. The genuine administrator privately enrolls a TOTP authenticator when required and verifies a fresh code to register the first trusted browser. The browser creates an ECDSA P-256 key pair and retains a non-extractable private CryptoKey in IndexedDB; the server stores the public JWK. Trust lasts thirty days from registration. A later password login in the same browser and origin proves possession of that key automatically, without requesting a code on every login. Routine reuse does not extend the trust period. This is browser-profile trust, not a hardware identity: a different browser, origin, cleared storage or unavailable key can require registration again.',
'Replacement while another trusted session is active. A different browser submits a session-bound approval request after password verification. The currently active trusted browser receives an in-website notification and may approve or deny it. The requesting browser must then complete fresh TOTP verification and sign its server-issued challenge. Approval alone does not authorize access. A successful server transaction replaces the trusted key and revokes the previous dashboard and attendance scopes; cancellation, denial or failed verification preserves the previous trust. Requests expire after two minutes, and signing challenges after ten minutes.',
'Availability, logout and recovery. The application polls for approval notifications while the trusted page is active; a heartbeat within two minutes determines whether an eligible approving session is recently active. This is not SMS, operating-system push, or proof that a physical device is online. When no eligible approving session is available, fresh authenticator verification provides the implemented replacement path. Normal logout retains browser trust, while Log out and forget this device revokes it. Lost authenticator access requires verified project-owner recovery. There is no password-only bypass or custom backup-code recovery. Device-signature authorization does not itself change the Auth JWT assurance level to AAL2.',
'Implementation and evidence. admin-device-trust.js coordinates browser-key proof, admin-device-approval.js handles approval notifications, and admin-mfa.js performs enrollment and fresh authenticator verification. The admin-device-trust Edge Function validates the signed-in account and session, verifies the signature and fresh TOTP evidence, and calls service-only completion functions. Database policies and session guards enforce the result independently of visible dialogs. User-supplied CLI output confirms application of migrations through 20261110000004 and deployment of admin-device-trust. These outputs do not establish successful physical two-browser transfer, authenticator use or matching Vercel frontend deployment; those remain acceptance checks.'
)
foreach($chapter in @(1,3)){
 $file=Join-Path $root "Chapter $chapter.docx";Copy-Item -LiteralPath $file -Destination (Join-Path $backup "Chapter $chapter original.docx")
 $work=Join-Path $backup "Chapter $chapter updated.docx";Copy-Item -LiteralPath $file -Destination $work
 $z=[IO.Compression.ZipFile]::Open($work,'Update')
 try{
  function ReadXml($part){$r=[IO.StreamReader]::new($z.GetEntry($part).Open());try{return ,([xml]$r.ReadToEnd())}finally{$r.Dispose()}}
  function SaveXml($part,$xml){$s=$z.GetEntry($part).Open();$s.SetLength(0);$wr=[IO.StreamWriter]::new($s,[Text.UTF8Encoding]::new($false));try{$xml.Save($wr)}finally{$wr.Dispose()}}
  function Binary($part,$file){$old=$z.GetEntry($part);if($old){$old.Delete()};$s=$z.CreateEntry($part).Open();try{$bytes=[IO.File]::ReadAllBytes($file);$s.Write($bytes,0,$bytes.Length)}finally{$s.Dispose()}}
  $doc=ReadXml 'word/document.xml';$n=[Xml.XmlNamespaceManager]::new($doc.NameTable);$n.AddNamespace('w',$w);$n.AddNamespace('a',$a);$n.AddNamespace('r',$relNs);$n.AddNamespace('wp','http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing')
  $body=$doc.SelectSingleNode('//w:body',$n)
  function Txt($p){($p.SelectNodes('.//w:t',$n)|ForEach-Object InnerText)-join ''}
  function Put($p,$text){$ts=@($p.SelectNodes('.//w:t',$n));if(-not $ts.Count){throw 'Text template missing'};$ts[0].InnerText=$text;foreach($t in @($ts|Select-Object -Skip 1)){$t.InnerText=''}}
  function Para($template,$text){$p=$template.CloneNode($true);foreach($b in @($p.SelectNodes('.//w:bookmarkStart|.//w:bookmarkEnd|w:pPr/w:sectPr',$n))){$null=$b.ParentNode.RemoveChild($b)};Put $p $text;return ,$p}
  $paras=@($body.SelectNodes('w:p',$n))
  if($chapter -eq 1){
   $target=@($paras|Where-Object {(Txt $_).StartsWith('Administrator MFA revision.') -or (Txt $_).StartsWith('Administrator trusted-browser security.')})
   if($target.Count -ne 1){throw 'Chapter 1 security anchor missing or ambiguous'}
   Put $target[0] ('Administrator trusted-browser security. The current revision authorizes one trusted browser per administrator account for thirty days. First registration requires a fresh authenticator code. Returning to the same browser requires the password and automatic browser-key proof. A replacement browser requests approval from an eligible active trusted session and then requires fresh authenticator verification; successful replacement revokes the previous trust and dashboard/scanner scopes. If no eligible approving session is recently active, the implemented fallback uses fresh authenticator verification. Normal logout retains trust; explicit forget-device logout revokes it. Staff and member login remain role-specific. In-website notifications require an active connection; SMS and operating-system push are outside this implementation. Three private security tables support approval, trusted public keys and session challenges. Authenticator loss requires verified project-owner recovery. Migration and function deployment are evidenced by user-supplied CLI output; live authenticator and two-browser acceptance tests remain to be completed.')
  }else{
   $rels=ReadXml 'word/_rels/document.xml.rels'
   $target=@($paras|Where-Object {(Txt $_).StartsWith('Administrator multi-factor authentication.')})
   if($target.Count -ne 1){throw 'Chapter 3 security anchor missing or ambiguous'}
   Put $target[0] $flow[0];$anchor=$target[0];foreach($t in $flow|Select-Object -Skip 1){$p=Para $target[0] $t;$null=$body.InsertAfter($p,$anchor);$anchor=$p}
   foreach($p in $paras){$t=(Txt $p).Trim()
    if($t.StartsWith('The complete application schema includes')){Put $p 'The eighteen application-owned tables comprise twelve public and six private tables, with 201 fields and twenty-seven declared foreign keys in the documented target schema. Figure 5 retains the twelve public tables, 162 fields and eighteen public foreign keys; the six private tables contain thirty-nine fields and nine foreign keys. The private tables are attendance_scan_requests, admin_login_attempts, account_sessions, admin_login_approvals, admin_trusted_devices and admin_device_sessions. Managed auth.users and auth.sessions are referenced structures, not additional application-owned tables. Counts reconcile the supplied pgAdmin baseline with migrations through 20261110000004; this is not a fresh live-schema introspection. UUID fields do not automatically imply relationships: activity_logs.actor_id, paired_device_id and the trusted-device snapshot/candidate identifiers have no declared foreign keys.'}
    elseif($t.StartsWith('Figure 5 covers all twelve')){Put $p 'Figure 5 covers all twelve public tables and their eighteen foreign-key relationships. Figure 5a supplements it with the three newly added private administrator-security tables and their six declared foreign keys. All eighteen application-owned tables and twenty-seven foreign keys are documented in the dictionary. Its Name, Type, Constraints and Description columns distinguish declared data types and sizes, primary/foreign/unique keys, composite constraints, nullability, referential actions and operational purpose. A line does not grant permission: server authorization controls access. The retained receipt_number field is an internal transaction reference and does not establish customer receipt issuance.'}
    elseif($t.StartsWith('User Login verifies an account')){Put $p 'User Login verifies an account and establishes access for its role and active-account state. All three actors participate. For administrators, this function also covers trusted-browser proof, initial TOTP registration, a replacement-browser approval request, approval or denial by the eligible active session, fresh TOTP before transfer, and explicit trust revocation. These are scenarios within the existing login capability, so Figure 4 retains nine function-level ovals. Both approving and requesting sessions represent the same Administrator actor; they do not create new organizational roles. User Management retains its existing profile and staff-account scope. Staff participation in that oval remains limited to authorized counter tasks and does not grant general personal-profile editing or staff-account administration.'}
    elseif($t.StartsWith('All three external entities communicate with Process 0')){Put $p 'All three external entities communicate with Process 0. Administrator input includes credentials, login-approval decisions and device-verification submissions; its returned security results include pending approval notices and authorization, rejection or replacement outcomes. These are security details of the existing administrator information exchange, not new external actors. Supabase Auth, browser-key verification and security storage remain internal to the boundary. Figure 2 therefore retains its three actors and single process. Figure 3 expands the system into nine functions, and Figure 3a identifies the additional individual security stores supporting User Login. The ERD and dictionary specify the persistent structures behind those exchanges.'}
   }
   $template=@($body.SelectNodes('w:p',$n)|Where-Object {(Txt $_).StartsWith('Supabase Auth verifies credentials and establishes')})[0]
   function Figure($stem,$caption,$description,$anchor){
    $picture=@($body.SelectNodes('w:p',$n)|Where-Object {$_.SelectSingleNode('.//a:blip',$n)})[0].CloneNode($true)
    foreach($v in @($picture.SelectNodes('w:pPr/w:sectPr|.//w:bookmarkStart|.//w:bookmarkEnd',$n))){$null=$v.ParentNode.RemoveChild($v)}
    $blip=$picture.SelectSingleNode('.//a:blip',$n);foreach($v in @($blip.ChildNodes)){$null=$blip.RemoveChild($v)}
    foreach($kind in @('png','svg')){$rid='rIdSecurity'+$stem.Substring(0,3)+$kind;$rel=$rels.CreateElement('Relationship',$rels.DocumentElement.NamespaceURI);$rel.SetAttribute('Id',$rid);$rel.SetAttribute('Type',$relNs+'/image');$rel.SetAttribute('Target',"media/$stem.$kind");$null=$rels.DocumentElement.AppendChild($rel);$source=if($kind -eq 'png'){Join-Path $diagrams "_Sources/$stem.png"}else{Join-Path $diagrams "$stem.svg"};Binary "word/media/$stem.$kind" $source
     if($kind -eq 'png'){$null=$blip.SetAttribute('embed',$relNs,$rid)}else{$list=$doc.CreateElement('a','extLst',$a);$ext=$doc.CreateElement('a','ext',$a);$ext.SetAttribute('uri','{96DAC541-7B7A-43D3-8B79-37D633B846F1}');$s=$doc.CreateElement('asvg','svgBlip','http://schemas.microsoft.com/office/drawing/2016/SVG/main');$null=$s.SetAttribute('embed',$relNs,$rid);$null=$ext.AppendChild($s);$null=$list.AppendChild($ext);$null=$blip.AppendChild($list)}
    }
    $drawing=Get-Content -Raw (Join-Path $diagrams "_Sources/$stem.json")|ConvertFrom-Json;$cx=[long](6.0*914400);$cy=[long]($cx*$drawing.H/$drawing.W)
    foreach($e in $picture.SelectNodes('.//wp:extent|.//a:xfrm/a:ext',$n)){$e.SetAttribute('cx',"$cx");$e.SetAttribute('cy',"$cy")}
    $prop=$picture.SelectSingleNode('.//wp:docPr',$n);$max=($doc.SelectNodes('//wp:docPr',$n)|ForEach-Object {[int]$_.id}|Measure-Object -Maximum).Maximum;$prop.SetAttribute('id',[string]($max+1));$prop.SetAttribute('name',$caption);$prop.SetAttribute('descr',$description)
    $null=$body.InsertAfter($picture,$anchor);$p=Para $template $caption;$null=$body.InsertAfter($p,$picture);$p2=Para $template $description;$null=$body.InsertAfter($p2,$p)
   }
   $dfd=@($body.SelectNodes('w:p',$n)|Where-Object {(Txt $_).StartsWith('Store identifiers remain consistent')})[0]
   Figure '03a-login-security-stores' 'Figure 3a. User Login - Additional Individual Security Stores' 'Figure 3a expands the security-storage view of Process 1.0 without introducing a tenth main function or combining physical stores. D15 records session-bound approval requests and decisions; D16 records the current trusted browser public key and trust period; D17 records candidate challenges and authorized session boundaries. Each has its own labeled connection. Two-headed summary arrows distinguish the records retrieved from the requests or results written; they do not imply identical data in both directions. Existing Auth identity, profile and account-scope exchanges remain in Figure 3. The Administrator represents both requesting and approving sessions. Verification and atomic trust replacement occur inside User Login, subject to the server checks described in the system flow.' $dfd
   $dictHeading=@($body.SelectNodes('w:p',$n)|Where-Object {(Txt $_).Trim() -eq 'Data Dictionary'})[0]
   Figure '05a-administrator-security-schema' 'Figure 5a. Administrator Security Schema Supplement' 'Figure 5a shows all columns of the three new private security tables. Each connection starts at a declared child foreign key and ends at a reference card for its managed Auth parent. Repeated auth.users and auth.sessions cards denote the same two managed tables, repeated only to prevent crossing lines. The three user_id references and the three Auth-session references make six foreign keys; approver_session_id uses ON DELETE SET NULL while the other five use CASCADE. Parent existence is mandatory for required foreign keys, while the nullable approver reference may be absent. The primary key on admin_trusted_devices.user_id permits at most one trusted row per administrator; it does not require every account to have one. The approval pair (requesting_session_id, session_scope) is unique as a pair. trusted_device_id and device_id do not acquire a relationship merely by sharing identifier values; the dictionary records their deliberate lack of foreign keys. Managed Auth internals remain outside the application-owned dictionary.' $dictHeading.PreviousSibling
   $tables=@($body.SelectNodes('w:tbl',$n));if($tables.Count -ne 20){throw 'Expected original dictionary before adding security tables'}
   $last=$tables[-1];$anchor=$last;$tableTemplate=$last
   for($ti=0;$ti -lt $model.tables.Count;$ti++){
    $t=$model.tables[$ti];$title=Para $template ('Table '+(21+$ti)+': '+$t.Name);$null=$body.InsertAfter($title,$anchor);$purpose=Para $template $t.Purpose;$null=$body.InsertAfter($purpose,$title)
    $new=$tableTemplate.CloneNode($true);$rows=@($new.SelectNodes('w:tr',$n));$rowTemplate=$rows[1].CloneNode($true);foreach($r in @($rows|Select-Object -Skip 1)){$null=$new.RemoveChild($r)}
    foreach($col in $t.Columns){$row=$rowTemplate.CloneNode($true);$cells=$row.SelectNodes('w:tc',$n);$constraints=if($col.Keys.Count){($col.Keys -join ', ')+'. '}else{''};$constraints+=if($col.Required){'NOT NULL. '}else{'Nullable at column level. '}
     foreach($fk in @($model.relations|Where-Object {$_.Child -eq $t.Name -and $_.Field -eq $col.Name})){$constraints+='References '+$fk.Parent+'('+$fk.ParentField+'); ON DELETE '+$fk.Delete+'; ON UPDATE NO ACTION. '}
     $constraints+=$col.Extra;Put $cells[0] $col.Name;Put $cells[1] $col.Type;Put $cells[2] $constraints.Trim();Put $cells[3] $col.Description;$null=$new.AppendChild($row)
    };$null=$body.InsertAfter($new,$purpose);$anchor=$new
   }
   SaveXml 'word/_rels/document.xml.rels' $rels
  }
  SaveXml 'word/document.xml' $doc
 }finally{$z.Dispose()}
}
# Check both original files are writable before replacing either one.
foreach($chapter in @(1,3)){$stream=[IO.File]::Open((Join-Path $root "Chapter $chapter.docx"),'Open','ReadWrite','None');$stream.Dispose()}
foreach($chapter in @(1,3)){Copy-Item -LiteralPath (Join-Path $backup "Chapter $chapter updated.docx") -Destination (Join-Path $root "Chapter $chapter.docx") -Force}
"Updated Chapters 1 and 3. Backup: $backup"
